  function patchVal(cur, pairs){
    if(cur==null) return cur;
    if(Array.isArray(cur)){
      return cur.map(function(item){
        for(var i=0;i<pairs.length;i++){ if(pairs[i].en===item) return pairs[i].it; }
        return item;
      });
    }
    if(typeof cur==='string'){
      for(var i=0;i<pairs.length;i++){ if(pairs[i].en===cur) return pairs[i].it; }
      if(pairs.length===1) return pairs[0].it;
    }
    return cur;
  }
